SELECT 'CONFIG id=' || c.id || ' name=' || c.name || ' uuid=' || coalesce(c.uuid::text,'<NULL>') || ' created=' || c.created_at::text FROM configurations c ORDER BY c.id;
SELECT 'IDX cfg=' || coalesce(o.configuration_id::text,'NULL') || ' slot=' || o.child_type || ' name=' || o.name || ' obj=' || coalesce(o.object_id,'NULL') FROM configuration_objects o WHERE o.child_type = ANY (ARRAY['SessionModule','ManagedApplicationModule','OrdinaryApplicationModule','ExternalConnectionModule']) ORDER BY 1;
SELECT 'CFGIDX cfg=' || c.id || ' slots=' || (SELECT count(*) FROM configuration_objects o WHERE o.configuration_id = c.id AND o.child_type = ANY (ARRAY['SessionModule','ManagedApplicationModule','OrdinaryApplicationModule','ExternalConnectionModule'])) FROM configurations c ORDER BY c.id;
